-- Phase 73 record of database changes ALREADY APPLIED to project hqvxhhhwzhefydvwlpje.
-- Do not re-run for the current Chef Mujahed production project.
CREATE TABLE IF NOT EXISTS public.staff_notification_preferences (user_id uuid PRIMARY KEY,web_push_enabled boolean NOT NULL DEFAULT true,telegram_enabled boolean NOT NULL DEFAULT true,event_types text[] NOT NULL DEFAULT ARRAY['NEW','AWAITING_CONFIRMATION','APPROVED','READY','OUT_FOR_DELIVERY','CANCELLED'],updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.staff_push_subscriptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,endpoint text NOT NULL UNIQUE,p256dh text NOT NULL,auth_key text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),failed_at timestamptz);
CREATE TABLE IF NOT EXISTS public.staff_telegram_links(user_id uuid PRIMARY KEY,chat_id bigint NOT NULL UNIQUE,linked_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.staff_telegram_link_codes(code_hash text PRIMARY KEY,user_id uuid NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS public.staff_notification_events(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,request_id uuid NOT NULL,reference text NOT NULL,event_type text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),processed_at timestamptz);
CREATE TABLE IF NOT EXISTS public.staff_notification_deliveries(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,event_id bigint NOT NULL REFERENCES public.staff_notification_events(id),user_id uuid NOT NULL,channel text NOT NULL,target text NOT NULL,status text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),error text,UNIQUE(event_id,channel,target));
ALTER TABLE public.staff_notification_preferences ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.staff_push_subscriptions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.staff_telegram_links ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.staff_telegram_link_codes ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.staff_notification_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.staff_notification_deliveries ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.staff_notification_preferences,public.staff_push_subscriptions,public.staff_telegram_links,public.staff_telegram_link_codes,public.staff_notification_events,public.staff_notification_deliveries FROM PUBLIC,anon,authenticated;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.staff_notification_preferences,public.staff_push_subscriptions,public.staff_telegram_links,public.staff_telegram_link_codes,public.staff_notification_events,public.staff_notification_deliveries TO service_role;
GRANT USAGE,SELECT ON SEQUENCE public.staff_notification_events_id_seq,public.staff_notification_deliveries_id_seq TO service_role;
CREATE OR REPLACE FUNCTION public.staff_notification_enqueue() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $body$
BEGIN
  IF NEW.deleted_at IS NOT NULL THEN RETURN NEW; END IF;
  IF TG_OP='INSERT' OR NEW.status IS DISTINCT FROM OLD.status THEN
    INSERT INTO public.staff_notification_events(request_id,reference,event_type)
    VALUES(NEW.id,NEW.reference,NEW.status);
  END IF;
  RETURN NEW;
END $body$;
REVOKE ALL ON FUNCTION public.staff_notification_enqueue() FROM PUBLIC,anon,authenticated;
DROP TRIGGER IF EXISTS staff_notification_request_event ON public.requests;
CREATE TRIGGER staff_notification_request_event AFTER INSERT OR UPDATE OF status ON public.requests FOR EACH ROW EXECUTE FUNCTION public.staff_notification_enqueue();
